146→        var aabbA = hasBoxA
147→            ? CollisionRect.FromBounds(entity.Get<BoxCollider>().Bounds, entity.Get<Transform>().Position)
148→            : entity.Get<ConvexCollider>().BroadPhaseAABB;
149→        var aabbB = hasBoxB
150→            ? CollisionRect.FromBounds(target.Get<BoxCollider>().Bounds, target.Get<Transform>().Position)
151→            : target.Get<ConvexCollider>().BroadPhaseAABB;
152→
153→        if (!aabbA.Intersects(aabbB)) return;
154→
155→        // Get world-space polygons for both entities
156→        Vector2[] polyA;
157→        Vector2[] polyB;
158→
159→        if (hasBoxA)
160→        {
161→            SATCollision.BoxToPolygon(entity.Get<BoxCollider>(), entity.Get<Transform>(), _boxPolyBufA);
162→            polyA = _boxPolyBufA;
163→        }
164→        else
165→        {
166→            polyA = entity.Get<ConvexCollider>().WorldVertices;
167→        }
168→
169→        if (hasBoxB)
170→        {
171→            SATCollision.BoxToPolygon(target.Get<BoxCollider>(), target.Get<Transform>(), _boxPolyBufB);
172→            polyB = _boxPolyBufB;
173→        }
174→        else
175→        {
176→            polyB = target.Get<ConvexCollider>().WorldVertices;
177→        }
178→
179→        if (!SATCollision.PolygonVsPolygon(polyA, polyB, out var contactNormal, out var penetrationDepth)) return;
180→
181→        // Contact point: midpoint of centroids
182→        var contactPoint = (SATCollision.PolygonCenter(polyA) + SATCollision.PolygonCenter(polyB)) / 2f;
183→
184→        foreach (var layer in colliderB.SharedLayers(colliderA))
185→        {
186→            _world.Publish(_createCollisionMessage(entity, target, contactPoint, contactNormal, 0f, penetrationDepth, layer));
187→        }
188→    }
