  1→using System;
  2→using Microsoft.Xna.Framework;
  3→using MonoDreams.Component;
  4→using MonoDreams.Component.Collision;
  5→
  6→namespace MonoDreams.Extensions.Monogame;
  7→
  8→/// <summary>
  9→/// Static helper for Separating Axis Theorem (SAT) collision detection between convex polygons.
 10→/// Produces the Minimum Translation Vector (MTV) — contact normal and penetration depth.
 11→/// </summary>
 12→public static class SATCollision
 13→{
 14→    /// <summary>
 15→    /// Tests two convex polygons for overlap using SAT.
 16→    /// Returns true if they overlap and outputs the MTV normal (pointing from polyA to polyB)
 17→    /// and penetration depth.
 18→    /// </summary>
 19→    public static bool PolygonVsPolygon(
 20→        ReadOnlySpan<Vector2> polyA,
 21→        ReadOnlySpan<Vector2> polyB,
 22→        out Vector2 normal,
 23→        out float depth)
 24→    {
 25→        normal = Vector2.Zero;
 26→        depth = float.MaxValue;
 27→
 28→        // Test axes from polygon A edges
 29→        for (var i = 0; i < polyA.Length; i++)
 30→        {
 31→            var next = (i + 1) % polyA.Length;
 32→            var edge = polyA[next] - polyA[i];
 33→            var axis = new Vector2(-edge.Y, edge.X); // perpendicular
 34→
 35→            var lengthSq = axis.LengthSquared();
 36→            if (lengthSq < 1e-12f) continue; // degenerate edge
 37→            axis /= MathF.Sqrt(lengthSq); // normalize
 38→
 39→            ProjectPolygon(polyA, axis, out var minA, out var maxA);
 40→            ProjectPolygon(polyB, axis, out var minB, out var maxB);
 41→
 42→            if (minA >= maxB || minB >= maxA)
 43→            {
 44→                // Separating axis found — no collision
 45→                depth = 0;
 46→                return false;
 47→            }
 48→
 49→            var overlap = MathF.Min(maxA - minB, maxB - minA);
 50→            if (overlap < depth)
 51→            {
 52→                depth = overlap;
 53→                normal = axis;
 54→            }
 55→        }
 56→
 57→        // Test axes from polygon B edges
 58→        for (var i = 0; i < polyB.Length; i++)
 59→        {
 60→            var next = (i + 1) % polyB.Length;
 61→            var edge = polyB[next] - polyB[i];
 62→            var axis = new Vector2(-edge.Y, edge.X);
 63→
 64→            var lengthSq = axis.LengthSquared();
 65→            if (lengthSq < 1e-12f) continue;
 66→            axis /= MathF.Sqrt(lengthSq);
 67→
 68→            ProjectPolygon(polyA, axis, out var minA, out var maxA);
 69→            ProjectPolygon(polyB, axis, out var minB, out var maxB);
 70→
 71→            if (minA >= maxB || minB >= maxA)
 72→            {
 73→                depth = 0;
 74→                return false;
 75→            }
 76→
 77→            var overlap = MathF.Min(maxA - minB, maxB - minA);
 78→            if (overlap < depth)
 79→            {
 80→                depth = overlap;
 81→                normal = axis;
 82→            }
 83→        }
 84→
 85→        // Ensure normal points from A's center toward B's center
 86→        var centerA = PolygonCenter(polyA);
 87→        var centerB = PolygonCenter(polyB);
 88→        var direction = centerB - centerA;
 89→        if (Vector2.Dot(direction, normal) < 0)
 90→        {
 91→            normal = -normal;
 92→        }
 93→
 94→        return true;
 95→    }
 96→
 97→    /// <summary>
 98→    /// Projects all vertices of a polygon onto an axis, returning min and max scalar values.
 99→    /// </summary>
100→    public static void ProjectPolygon(ReadOnlySpan<Vector2> polygon, Vector2 axis, out float min, out float max)
101→    {
102→        min = float.MaxValue;
103→        max = float.MinValue;
104→
105→        for (var i = 0; i < polygon.Length; i++)
106→        {
107→            var projection = Vector2.Dot(polygon[i], axis);
108→            if (projection < min) min = projection;
109→            if (projection > max) max = projection;
110→        }
111→    }
112→
113→    /// <summary>
114→    /// Computes the centroid (average of vertices) of a convex polygon.
115→    /// </summary>
116→    public static Vector2 PolygonCenter(ReadOnlySpan<Vector2> polygon)
117→    {
118→        var center = Vector2.Zero;
119→        for (var i = 0; i < polygon.Length; i++)
120→        {
121→            center += polygon[i];
122→        }
123→        return center / polygon.Length;
124→    }
125→
126→    /// <summary>
127→    /// Converts a BoxCollider + Transform into a 4-vertex polygon in world space,
128→    /// suitable for SAT testing against ConvexCollider entities.
129→    /// </summary>
130→    public static void BoxToPolygon(BoxCollider box, Transform transform, Span<Vector2> output)
131→    {
132→        var pos = transform.Position;
133→        var bounds = box.Bounds;
134→
135→        output[0] = new Vector2(pos.X + bounds.Left, pos.Y + bounds.Top);
136→        output[1] = new Vector2(pos.X + bounds.Right, pos.Y + bounds.Top);
137→        output[2] = new Vector2(pos.X + bounds.Right, pos.Y + bounds.Bottom);
138→        output[3] = new Vector2(pos.X + bounds.Left, pos.Y + bounds.Bottom);
139→    }
140→
141→    /// <summary>
142→    /// Computes the axis-aligned bounding box encompassing all vertices.
143→    /// Used as broad-phase rejection before running full SAT.
144→    /// </summary>
