  1→using System.Text.Json;
  2→using DefaultEcs;
  3→using DefaultEcs.System;
  4→using Microsoft.Xna.Framework;
  5→using Microsoft.Xna.Framework.Content;
  6→using Microsoft.Xna.Framework.Graphics;
  7→using System;
  8→using System.Collections.Generic;
  9→using System.IO;
 10→using System.Linq;
 11→using MonoDreams.Component;
 12→using MonoDreams.Component.Collision;
 13→using MonoDreams.Component.Physics;
 14→using MonoDreams.Component.Draw;
 15→using MonoDreams.Level;
 16→using MonoDreams.Message.Level;
 17→using MonoDreams.Draw;
 18→using MonoDreams.Extension;
 19→using MonoDreams.State;
 20→using Logger = MonoDreams.State.Logger;
 21→
 22→namespace MonoDreams.System.Level;
 23→
 24→/// <summary>
 25→/// Parses Blender-exported JSON level files and creates entities for meshes.
 26→/// Handles LoadLevelRequest messages where the identifier starts with "Blender_".
 27→/// </summary>
 28→public sealed class BlenderLevelParserSystem : ISystem<GameState>
 29→{
 30→    private const float DEFAULT_LAYER_DEPTH = 0.5f;
 31→
 32→    private readonly World _world;
 33→    private readonly ContentManager _content;
 34→    private readonly MonoDreams.Component.Camera _camera;
 35→    private readonly Dictionary<string, Texture2D> _loadedTextures = new();
 36→    private readonly HashSet<Entity> _blenderEntities = new();
 37→    private readonly Dictionary<string, Entity> _nameToEntity = new();
 38→    private readonly Dictionary<string, Action<Entity, BlenderObject>> _collectionHandlers = new();
 39→    private DrawLayerMap _drawLayerMap;
 40→
 41→    public bool IsEnabled { get; set; } = true;
 42→
 43→    public BlenderLevelParserSystem(World world, ContentManager content, MonoDreams.Component.Camera camera)
 44→    {
 45→        _world = world ?? throw new ArgumentNullException(nameof(world));
 46→        _content = content ?? throw new ArgumentNullException(nameof(content));
 47→        _camera = camera ?? throw new ArgumentNullException(nameof(camera));
 48→
 49→        _world.Subscribe<LoadLevelRequest>(OnLoadLevelRequest);
 50→    }
 51→
 52→    /// <summary>
 53→    /// Registers a handler that will be called for entities belonging to the specified Blender collection.
 54→    /// This allows game code to add game-specific components to entities created by the core parser.
 55→    /// </summary>
 56→    public void RegisterCollectionHandler(string collectionName, Action<Entity, BlenderObject> handler)
 57→    {
 58→        _collectionHandlers[collectionName] = handler ?? throw new ArgumentNullException(nameof(handler));
 59→    }
 60→
 61→    /// <summary>
 62→    /// Sets the draw layer map used for depth resolution. When set, mesh depth is resolved by:
 63→    /// 1. Object's "drawLayer" custom property (string matching a layer name)
 64→    /// 2. Blender collection names matched against layer names
 65→    /// 3. Falls back to DEFAULT_LAYER_DEPTH
 66→    /// </summary>
 67→    public void SetDrawLayerMap(DrawLayerMap drawLayerMap)
 68→    {
 69→        _drawLayerMap = drawLayerMap ?? throw new ArgumentNullException(nameof(drawLayerMap));
 70→    }
 71→
 72→    [Subscribe]
 73→    private void OnLoadLevelRequest(in LoadLevelRequest request)
 74→    {
 75→        if (!IsEnabled) return;
 76→
 77→        // Only handle Blender levels
 78→        if (!request.LevelIdentifier.StartsWith("Blender_"))
 79→            return;
 80→
 81→        Logger.Info($"Loading Blender level: {request.LevelIdentifier}");
 82→
 83→        // Clean up previous entities
 84→        CleanupEntities();
 85→
 86→        try
 87→        {
 88→            // Load JSON file from Content directory
 89→            // The Content.RootDirectory gives us the path to the Content folder
 90→            var jsonPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, _content.RootDirectory, "blender_level.json");
 91→            Logger.Debug($"Loading Blender level from: {jsonPath}");
 92→            var jsonContent = File.ReadAllText(jsonPath);
 93→
 94→            var options = new JsonSerializerOptions
 95→            {
 96→                PropertyNameCaseInsensitive = true
 97→            };
 98→
 99→            var levelData = JsonSerializer.Deserialize<BlenderLevelData>(jsonContent, options);
100→
101→            if (levelData?.Objects == null)
102→            {
103→                Logger.Warning("No objects found in Blender level data.");
104→                return;
105→            }
106→
107→            Logger.Info($"Loaded {levelData.Objects.Count} objects from Blender level.");
108→
109→            // Pre-scan: identify collider children (names ending with "-collider" that have a parent)
110→            var colliderChildMap = new Dictionary<string, BlenderObject>();   // parent name → collider data
111→            var colliderChildNames = new HashSet<string>();
112→            foreach (var obj in levelData.Objects)
113→            {
114→                if (obj.Name.EndsWith("-collider") && !string.IsNullOrEmpty(obj.Parent))
115→                {
116→                    colliderChildMap[obj.Parent] = obj;
117→                    colliderChildNames.Add(obj.Name);
118→                    Logger.Debug($"Found collider child '{obj.Name}' for parent '{obj.Parent}'.");
119→                }
120→            }
121→
122→            // Pass 1: Create all entities (skip collider children)
123→            foreach (var obj in levelData.Objects)
124→            {
125→                if (colliderChildNames.Contains(obj.Name))
126→                {
127→                    Logger.Debug($"Skipping collider child '{obj.Name}' (will be applied to parent).");
128→                    continue;
129→                }
130→
131→                switch (obj.Type)
132→                {
133→                    case "CAMERA":
134→                        ProcessCamera(obj, levelData.ScaleFactor);
135→                        break;
136→                    case "MESH":
137→                    case "GREASEPENCIL":
138→                        ProcessMesh(obj, levelData);
139→                        break;
140→                    case "EMPTY":
141→                        ProcessEmpty(obj);
142→                        break;
143→                    default:
144→                        Logger.Warning($"Skipping unknown object type: {obj.Type}");
145→                        break;
146→                }
147→            }
148→
149→            // Post-Pass 1: Apply collider children to parent entities
150→            foreach (var (parentName, colliderObj) in colliderChildMap)
151→            {
152→                ApplyColliderChild(parentName, colliderObj);
153→            }
154→
155→            // Pass 2: Set up parent-child relationships
156→            foreach (var obj in levelData.Objects)
157→            {
158→                if (string.IsNullOrEmpty(obj.Parent)) continue;
159→                if (colliderChildNames.Contains(obj.Name)) continue;
160→
161→                if (!_nameToEntity.TryGetValue(obj.Name, out var childEntity))
162→                {
163→                    Logger.Warning($"Parent linkage: child '{obj.Name}' not found in entity map.");
164→                    continue;
165→                }
166→                if (!_nameToEntity.TryGetValue(obj.Parent, out var parentEntity))
167→                {
168→                    Logger.Warning($"Parent linkage: parent '{obj.Parent}' not found for child '{obj.Name}'.");
169→                    continue;
170→                }
171→
172→                childEntity.SetParent(parentEntity);
173→                Logger.Debug($"Set parent of '{obj.Name}' to '{obj.Parent}'.");
174→            }
175→
176→            // Post-Pass 2: Propagate YSortOffset from parents to sprite children
177→            foreach (var obj in levelData.Objects)
178→            {
179→                if (string.IsNullOrEmpty(obj.Parent)) continue;
180→                if (colliderChildNames.Contains(obj.Name)) continue;
181→
182→                if (!_nameToEntity.TryGetValue(obj.Name, out var childEntity)) continue;
183→                if (!_nameToEntity.TryGetValue(obj.Parent, out var parentEntity)) continue;
184→
185→                if (childEntity.Has<SpriteInfo>() && parentEntity.Has<SpriteInfo>())
186→                {
187→                    ref readonly var parentSprite = ref parentEntity.Get<SpriteInfo>();
188→                    if (parentSprite.YSortOffset != 0f)
189→                    {
190→                        ref var childSprite = ref childEntity.Get<SpriteInfo>();
191→                        childSprite.YSortOffset = parentSprite.YSortOffset;
192→                        Logger.Debug($"Propagated YSortOffset={parentSprite.YSortOffset} from '{obj.Parent}' to '{obj.Name}'.");
193→                    }
194→                }
195→            }
196→
197→            Logger.Info($"Created {_blenderEntities.Count} entities from Blender level.");
198→        }
199→        catch (Exception ex)
200→        {
201→            Logger.Error($"Error loading Blender level: {ex.Message}\n{ex.StackTrace}");
202→        }
203→    }
204→
205→    private void ProcessCamera(BlenderObject cameraObj, float scaleFactor)
206→    {
207→        if (cameraObj.Position == null) return;
208→
209→        var cameraPosition = new Vector2(cameraObj.Position.X, cameraObj.Position.Y);
210→        _camera.Position = cameraPosition;
211→
212→        // Read ortho_scale from custom properties and convert to game zoom
213→        // Blender ortho_scale = visible width in Blender units
214→        // With scaleFactor, visible world pixels = ortho_scale * scaleFactor
215→        // Game zoom = virtualWidth / visible_world_pixels
216→        if (cameraObj.CustomProperties?.TryGetValue("zoom", out var zoomValue) == true)
217→        {
218→            if (zoomValue is JsonElement jsonElement && jsonElement.TryGetDouble(out var orthoScale))
219→            {
220→                // Convert Blender ortho_scale to game zoom
221→                var visibleWorldWidth = orthoScale * scaleFactor;
222→                var gameZoom = _camera.VirtualWidth / visibleWorldWidth;
223→                _camera.Zoom = (float)gameZoom;
224→                Logger.Debug($"Set camera zoom to {gameZoom} (from Blender ortho_scale {orthoScale}, scaleFactor {scaleFactor})");
225→            }
226→        }
227→
228→        Logger.Debug($"Set camera position to ({cameraPosition.X}, {cameraPosition.Y})");
229→    }
230→
231→    private void ProcessEmpty(BlenderObject emptyObj)
232→    {
233→        var entity = _world.CreateEntity();
234→        _blenderEntities.Add(entity);
235→
236→        var position = new Vector2(
237→            emptyObj.Position?.X ?? 0,
238→            emptyObj.Position?.Y ?? 0
239→        );
240→
241→        entity.Set(new Transform(position));
242→        entity.Set(new EntityInfo("Empty", emptyObj.Name));
243→
244→        _nameToEntity[emptyObj.Name] = entity;
245→
246→        // Invoke registered game-specific collection handlers
247→        if (emptyObj.Collections != null)
248→        {
249→            foreach (var collection in emptyObj.Collections)
250→            {
251→                if (_collectionHandlers.TryGetValue(collection, out var handler))
252→                {
253→                    handler(entity, emptyObj);
254→                }
255→            }
256→        }
257→
258→        Logger.Debug($"Created empty entity '{emptyObj.Name}' at ({position.X}, {position.Y})");
259→    }
260→
261→    private void ProcessMesh(BlenderObject meshObj, BlenderLevelData levelData)
262→    {
263→        if (meshObj.UvMapping == null)
264→        {
265→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - no UV mapping.");
266→            return;
267→        }
268→
269→        // Extract content path from texture path
270→        var contentPath = ExtractContentPath(meshObj.UvMapping.TexturePath);
271→        if (string.IsNullOrEmpty(contentPath))
272→        {
273→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - invalid texture path: {meshObj.UvMapping.TexturePath}");
274→            return;
275→        }
276→
277→        // Load texture
278→        Texture2D texture;
279→        if (!_loadedTextures.TryGetValue(contentPath, out texture))
280→        {
281→            try
282→            {
283→                texture = _content.Load<Texture2D>(contentPath);
284→                _loadedTextures[contentPath] = texture;
285→                Logger.Debug($"Loaded texture: {contentPath}");
286→            }
287→            catch (Exception ex)
288→            {
289→                Logger.Error($"Failed to load texture '{contentPath}': {ex.Message}");
290→                return;
291→            }
292→        }
293→
294→        // Get UV coordinates from first layer
295→        var uvLayer = meshObj.UvMapping.UvLayers?.FirstOrDefault();
296→        if (uvLayer?.UvCoordinates == null || uvLayer.UvCoordinates.Count == 0)
297→        {
298→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - no UV coordinates.");
299→            return;
300→        }
301→
302→        // Calculate source rectangle from UV coordinates
303→        var sourceRect = CalculateSourceRect(uvLayer.UvCoordinates, texture);
304→
305→        // Create entity
306→        var entity = _world.CreateEntity();
307→        _blenderEntities.Add(entity);
308→        _nameToEntity[meshObj.Name] = entity;
309→
310→        // Position from Blender
311→        var position = new Vector2(
312→            meshObj.Position?.X ?? 0,
313→            meshObj.Position?.Y ?? 0
314→        );
315→
316→        // Transform
317→        entity.Set(new Transform(position));
318→
319→        // SpriteInfo with calculated source rectangle
320→        // Use mesh dimensions from Blender for Size (already scaled), fallback to source rect if not available
321→        var size = new Vector2(
322→            meshObj.Dimensions?.X ?? sourceRect.Width,
323→            meshObj.Dimensions?.Y ?? sourceRect.Height
324→        );
325→
326→        // Calculate origin from Blender's origin offset
327→        // Blender origin offset is normalized (0-1) where (0,0) is bottom-left and (0.5,0.5) is center
328→        // SpriteBatch.Draw expects origin in SOURCE TEXTURE coordinates (not destination size)
329→        var originOffsetX = meshObj.OriginOffset?.X ?? 0.5f;  // Default to center
330→        var originOffsetY = meshObj.OriginOffset?.Y ?? 0.5f;
331→        // Y is inverted: Blender Y=0 is bottom, engine Y=0 is top
332→        // Use sourceRect dimensions since SpriteBatch.Draw origin is in source coordinates
333→        var origin = new Vector2(sourceRect.Width * originOffsetX, sourceRect.Height * (1 - originOffsetY));
334→
335→        entity.Set(new SpriteInfo
336→        {
337→            SpriteSheet = texture,
338→            Source = sourceRect,
339→            Size = size,
340→            Color = Color.White,
341→            Target = RenderTargetID.Main,
342→            LayerDepth = ResolveLayerDepth(meshObj, levelData),
343→            Origin = origin
344→        });
345→
346→        // DrawComponent
347→        entity.Set(new DrawComponent
348→        {
349→            Type = DrawElementType.Sprite,
350→            Target = RenderTargetID.Main
351→        });
352→
353→        // Make visible
354→        entity.Set(new Visible());
355→
356→        // Process collection-based components
357→        ProcessCollections(entity, meshObj, size);
358→
359→        Logger.Debug($"Created entity for mesh '{meshObj.Name}' at ({position.X}, {position.Y}) with size ({size.X}, {size.Y}), origin ({origin.X}, {origin.Y}), and source rect ({sourceRect.X}, {sourceRect.Y}, {sourceRect.Width}, {sourceRect.Height})");
360→    }
361→
362→    /// <summary>
363→    /// Resolves the layer depth for a mesh object using the DrawLayerMap (if set).
364→    /// Priority: object "drawLayer" custom property > collection name match (with hierarchy walk) > DEFAULT_LAYER_DEPTH.
365→    /// </summary>
366→    private float ResolveLayerDepth(BlenderObject meshObj, BlenderLevelData levelData)
367→    {
368→        if (_drawLayerMap == null)
369→            return DEFAULT_LAYER_DEPTH;
370→
371→        // 1. Check object's "drawLayer" custom property
372→        if (meshObj.CustomProperties?.TryGetValue("drawLayer", out var drawLayerValue) == true)
373→        {
374→            var layerName = drawLayerValue is JsonElement jsonEl
375→                ? jsonEl.GetString()
376→                : drawLayerValue?.ToString();
377→
378→            if (layerName != null && _drawLayerMap.TryGetDepth(layerName, out var depth))
379→                return depth;
380→        }
381→
382→        // 2. Try each Blender collection name, then walk up the collection hierarchy
383→        if (meshObj.Collections != null)
384→        {
385→            foreach (var collection in meshObj.Collections)
386→            {
387→                var current = collection;
388→                while (current != null)
389→                {
390→                    if (_drawLayerMap.TryGetDepth(current, out var depth))
391→                        return depth;
392→
393→                    // Walk up the hierarchy if available
394→                    if (levelData.CollectionHierarchy == null ||
395→                        !levelData.CollectionHierarchy.TryGetValue(current, out current))
396→                        break;
397→                }
398→            }
399→        }
400→
401→        // 3. Fall back to default
402→        return DEFAULT_LAYER_DEPTH;
403→    }
404→
405→    /// <summary>
406→    /// Extracts the MonoGame Content path from a full file system path.
407→    /// Finds "/Content/" and returns the substring after it, without file extension.
408→    /// </summary>
409→    private static string ExtractContentPath(string fullPath)
410→    {
411→        if (string.IsNullOrEmpty(fullPath))
412→            return null;
413→
414→        var contentIndex = fullPath.IndexOf("/Content/", StringComparison.OrdinalIgnoreCase);
415→        if (contentIndex < 0)
416→        {
417→            // Try Windows-style path
418→            contentIndex = fullPath.IndexOf("\\Content\\", StringComparison.OrdinalIgnoreCase);
419→        }
420→
421→        if (contentIndex < 0)
422→            return null;
423→
424→        var separatorLength = "/Content/".Length;
425→        var relativePath = fullPath.Substring(contentIndex + separatorLength);
426→
427→        // Remove file extension
428→        var extensionIndex = relativePath.LastIndexOf('.');
429→        if (extensionIndex > 0)
430→        {
431→            relativePath = relativePath.Substring(0, extensionIndex);
432→        }
433→
434→        return relativePath;
435→    }
436→
437→    /// <summary>
438→    /// Calculates a source rectangle from UV coordinates.
439→    /// Assumes a plane mesh with 4 vertices.
440→    /// </summary>
441→    private static Rectangle CalculateSourceRect(List<UvCoordinate> uvCoords, Texture2D texture)
442→    {
443→        if (uvCoords == null || uvCoords.Count == 0)
444→            return Rectangle.Empty;
445→
446→        float minU = uvCoords.Min(uv => uv.U);
447→        float maxU = uvCoords.Max(uv => uv.U);
448→        float minV = uvCoords.Min(uv => uv.V);
449→        float maxV = uvCoords.Max(uv => uv.V);
450→
451→        // Convert UV to pixel coordinates with rounding for better precision
452→        // UV origin is bottom-left, texture origin is top-left, so flip V
453→        int x = (int)Math.Round(minU * texture.Width);
454→        int y = (int)Math.Round((1 - maxV) * texture.Height);
455→        int width = (int)Math.Round((maxU - minU) * texture.Width);
456→        int height = (int)Math.Round((maxV - minV) * texture.Height);
457→
458→        return new Rectangle(x, y, width, height);
459→    }
460→
461→    /// <summary>
462→    /// Processes Blender collection membership and adds appropriate components.
463→    /// Collection names determine entity behavior (e.g., "Collision" adds BoxCollider).
464→    /// Collection custom properties can configure component settings.
465→    /// </summary>
466→    private void ProcessCollections(Entity entity, BlenderObject meshObj, Vector2 size)
467→    {
468→        if (meshObj.Collections == null || meshObj.Collections.Count == 0)
469→            return;
470→
471→        // Compute visual offset from origin so collision boxes align with rendered sprites.
472→        // SpriteBatch.Draw renders at: position - origin * scale
473→        // In destination space: offset = -(size * originOffset)
474→        var originOffsetX = meshObj.OriginOffset?.X ?? 0.5f;
475→        var originOffsetY = meshObj.OriginOffset?.Y ?? 0.5f;
476→        // Compute float edges of visual bounds relative to entity position
477→        float left = -size.X * originOffsetX;
478→        float top = -size.Y * (1 - originOffsetY);  // Y inverted: Blender Y=0 is bottom
479→        // Snap to smallest enclosing integer rectangle (floor expands left/top, ceiling expands right/bottom)
480→        int intLeft = (int)Math.Floor(left);
481→        int intTop = (int)Math.Floor(top);
482→        int intRight = (int)Math.Ceiling(left + size.X);
483→        int intBottom = (int)Math.Ceiling(top + size.Y);
484→
485→        var boundsOffset = new Point(intLeft, intTop);
486→        var boundsSize = new Point(intRight - intLeft, intBottom - intTop);
487→
488→        // Check for Collision collection
489→        if (meshObj.Collections.Contains("Collision"))
490→        {
491→            entity.Set(new EntityInfo("Collision", meshObj.Name));
492→
493→            // Get collision layer from collection properties (default to -1 for all layers)
494→            int layer = -1;
495→            bool passive = false;
496→
497→            if (meshObj.CollectionProperties?.TryGetValue("Collision", out var collisionProps) == true)
498→            {
499→                layer = GetIntProperty(collisionProps, "layer", -1);
500→                passive = GetBoolProperty(collisionProps, "passive", false);
501→            }
502→
503→            var bounds = new Rectangle(boundsOffset, boundsSize);
504→            var activeLayers = new HashSet<int> { layer };
505→            entity.Set(new BoxCollider(bounds, activeLayers, passive));
506→
507→            Logger.Debug($"Added BoxCollider to '{meshObj.Name}' (layer: {layer}, passive: {passive})");
508→        }
509→
510→        // Check for Player collection
511→        if (meshObj.Collections.Contains("Player"))
512→        {
513→            entity.Set(new EntityInfo("Player", meshObj.Name));
514→            entity.Set(new BoxCollider(new Rectangle(boundsOffset, boundsSize)));
515→            entity.Set(new RigidBody());
516→            entity.Set(new Velocity());
517→
518→            // Add camera follow target component
519→            entity.Set(new CameraFollowTarget
520→            {
521→                DampingX = 5.0f,
522→                DampingY = 5.0f,
523→                MaxDistanceX = 150.0f,
524→                MaxDistanceY = 100.0f,
525→                IsActive = true
526→            });
527→            Logger.Debug($"Set Player for '{meshObj.Name}'");
528→        }
529→
530→        // Check for Enemy collection
531→        if (meshObj.Collections.Contains("Enemy"))
532→        {
533→            entity.Set(new EntityInfo("Enemy", meshObj.Name));
534→            Logger.Debug($"Set Enemy for '{meshObj.Name}'");
535→        }
536→
537→        // Check for Trigger collection (collision but no physics push)
538→        if (meshObj.Collections.Contains("Trigger"))
539→        {
540→            if (!entity.Has<BoxCollider>())
541→            {
542→                var bounds = new Rectangle(boundsOffset, boundsSize);
543→                entity.Set(new BoxCollider(bounds, passive: true));
544→            }
545→            entity.Set(new EntityInfo("Trigger", meshObj.Name));
546→            Logger.Debug($"Set as Trigger zone for '{meshObj.Name}'");
547→        }
548→
549→        // Invoke registered game-specific collection handlers
550→        foreach (var collection in meshObj.Collections)
551→        {
552→            if (_collectionHandlers.TryGetValue(collection, out var handler))
553→            {
554→                handler(entity, meshObj);
555→            }
556→        }
557→    }
558→
559→    /// <summary>
560→    /// Applies a collider child's mesh vertices as a ConvexCollider on the parent entity.
561→    /// Replaces any existing BoxCollider (preserving its layer/passive settings).
562→    /// Sets YSortOffset on the parent's SpriteInfo and adds ColliderTag.
563→    /// </summary>
564→    private void ApplyColliderChild(string parentName, BlenderObject colliderObj)
565→    {
566→        if (!_nameToEntity.TryGetValue(parentName, out var parentEntity))
567→        {
568→            Logger.Warning($"Collider child '{colliderObj.Name}': parent entity '{parentName}' not found.");
569→            return;
570→        }
571→
572→        if (colliderObj.Vertices == null || colliderObj.Vertices.Count < 3)
573→        {
574→            Logger.Warning($"Collider child '{colliderObj.Name}': needs at least 3 vertices, got {colliderObj.Vertices?.Count ?? 0}.");
575→            return;
576→        }
577→
578→        // Build model vertices from exported data
579→        var modelVertices = new Vector2[colliderObj.Vertices.Count];
580→        for (var i = 0; i < colliderObj.Vertices.Count; i++)
581→        {
582→            modelVertices[i] = new Vector2(colliderObj.Vertices[i].X, colliderObj.Vertices[i].Y);
583→        }
584→
585→        // Guard against degenerate shapes (e.g. all vertices collinear or on the same axis)
586→        float minX = float.MaxValue, maxX = float.MinValue;
587→        float minY = float.MaxValue, maxY = float.MinValue;
588→        foreach (var v in modelVertices)
589→        {
590→            if (v.X < minX) minX = v.X;
591→            if (v.X > maxX) maxX = v.X;
592→            if (v.Y < minY) minY = v.Y;
593→            if (v.Y > maxY) maxY = v.Y;
594→        }
595→        if (maxX - minX < 0.01f || maxY - minY < 0.01f)
596→        {
597→            Logger.Warning($"Collider child '{colliderObj.Name}': degenerate shape (width={maxX - minX}, height={maxY - minY}), skipping.");
598→            return;
599→        }
600→
601→        // Determine collision layer and passive flag
602→        HashSet<int> activeLayers = null;
603→        bool passive = false;
604→
605→        // If parent already has a BoxCollider (from ProcessCollections), inherit its settings and remove it
606→        if (parentEntity.Has<BoxCollider>())
607→        {
608→            ref readonly var existingBox = ref parentEntity.Get<BoxCollider>();
609→            activeLayers = existingBox.ActiveLayers;
610→            passive = existingBox.Passive;
611→            parentEntity.Remove<BoxCollider>();
612→            Logger.Debug($"Replaced BoxCollider on '{parentName}' with ConvexCollider from '{colliderObj.Name}'.");
613→        }
614→        else
615→        {
616→            // Check collider child's own collection properties for collision settings
617→            if (colliderObj.CollectionProperties != null)
618→            {
619→                foreach (var (_, props) in colliderObj.CollectionProperties)
620→                {
621→                    var layer = GetIntProperty(props, "layer", -1);
622→                    passive = GetBoolProperty(props, "passive", false);
623→                    activeLayers = new HashSet<int> { layer };
624→                    break;
625→                }
626→            }
627→        }
628→
629→        // Create ConvexCollider with rotation ignored (baked into model vertices)
630→        parentEntity.Set(new ConvexCollider(modelVertices, activeLayers, passive, ignoreTransformRotation: true));
631→
632→        // Set YSortOffset = max Y of model vertices (bottom of collider in Y-down coords)
633→        // maxY was already computed in the degenerate-shape guard above
634→        if (parentEntity.Has<SpriteInfo>())
635→        {
636→            ref var spriteInfo = ref parentEntity.Get<SpriteInfo>();
637→            spriteInfo.YSortOffset = maxY;
638→        }
639→
640→        // Add ColliderTag
641→        parentEntity.Set(new ColliderTag());
642→
643→        Logger.Debug($"Applied ConvexCollider from '{colliderObj.Name}' to '{parentName}' ({modelVertices.Length} vertices, YSortOffset={maxY}).");
644→    }
645→
646→    /// <summary>
647→    /// Gets an integer property from collection properties dictionary.
648→    /// </summary>
649→    private static int GetIntProperty(Dictionary<string, object> props, string key, int defaultValue)
650→    {
651→        if (props == null || !props.TryGetValue(key, out var value))
652→            return defaultValue;
653→
654→        if (value is JsonElement jsonElement)
655→        {
656→            if (jsonElement.TryGetInt32(out var intVal))
657→                return intVal;
658→            if (jsonElement.TryGetDouble(out var doubleVal))
659→                return (int)doubleVal;
660→        }
661→
662→        if (value is int intValue)
663→            return intValue;
664→        if (value is double doubleValue)
665→            return (int)doubleValue;
666→        if (value is float floatValue)
667→            return (int)floatValue;
668→
669→        return defaultValue;
670→    }
671→
672→    /// <summary>
673→    /// Gets a boolean property from collection properties dictionary.
674→    /// </summary>
675→    private static bool GetBoolProperty(Dictionary<string, object> props, string key, bool defaultValue)
676→    {
677→        if (props == null || !props.TryGetValue(key, out var value))
678→            return defaultValue;
679→
680→        if (value is JsonElement jsonElement)
681→        {
682→            if (jsonElement.ValueKind == JsonValueKind.True)
683→                return true;
684→            if (jsonElement.ValueKind == JsonValueKind.False)
685→                return false;
686→        }
687→
688→        if (value is bool boolValue)
689→            return boolValue;
690→
691→        return defaultValue;
692→    }
693→
694→    private void CleanupEntities()
695→    {
696→        Logger.Info($"Cleaning up {_blenderEntities.Count} Blender entities...");
697→        foreach (var entity in _blenderEntities.ToArray())
698→        {
699→            if (entity.IsAlive)
700→            {
701→                entity.Dispose();
702→            }
703→        }
704→        _blenderEntities.Clear();
705→        _nameToEntity.Clear();
706→    }
707→
708→    public void Update(GameState state)
709→    {
710→        // Processing happens via message subscription
711→    }
712→
713→    public void Dispose()
714→    {
715→        CleanupEntities();
716→        _loadedTextures.Clear();
717→        GC.SuppressFinalize(this);
718→    }
719→}
