 71→        _viewportManager = viewportManager;
 72→        _parallelRunner = parallelRunner;
 73→        _spriteBatch = spriteBatch;
 74→        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
 75→        {
 76→            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) },
 77→            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) },
 78→            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) }
 79→        };
 80→        
 81→        camera.Position = new Vector2(0, 0);
 82→
 83→        _layers = DrawLayerMap.FromEnum<GameDrawLayer>()
 84→            .WithYSort(GameDrawLayer.Characters);
