 93→    public void Load(ScreenController screenController, ContentManager content)
 94→    {
 95→#if DEBUG
 96→        // Wire debug inspector input suppression
 97→        var debugInspector = screenController.Game.Services.GetService(typeof(DebugInspector)) as DebugInspector;
 98→        if (debugInspector != null)
