+        cross = ax * by - ay * bx
+        if abs(cross) < 1e-9:
+            continue  # collinear edge, skip
+        current_sign = cross > 0
+        if sign is None:
+            sign = current_sign
+        elif current_sign != sign:
+            print(f"WARNING: mesh '{obj.name}' is not convex — SAT requires convex polygons. Skipping vertices.")
+            return None
